@once
<template id="flow-person-button"><button type="button" class="person-button"><span class="avatar" data-initials></span><span class="min-w-0 grow"><strong class="block text-[13px] font-semibold" data-name></strong><span class="block text-xs text-muted" data-status></span></span></button></template>
<template id="flow-score-sheet"><section data-score-content data-panel-group>
<div class="person-heading mb-4 flex flex-wrap items-start gap-3"><span class="avatar size-9!" data-initials></span><div class="min-w-0 grow"><p class="mb-1 text-xs font-semibold text-success" data-kind></p><h2 class="text-lg font-semibold" data-name></h2><p class="mt-1 text-xs text-muted" data-person-meta></p><p class="mt-1 text-xs text-muted" data-template-meta></p></div><span class="status" data-status></span></div>
<div class="notice notice-warning mb-3" data-return-reason hidden></div><div class="notice mb-3" data-lock-reason hidden></div>
<div class="seg w-fit mb-3" role="tablist" aria-label="Bagian penilaian"><button type="button" class="active" data-panel-tab="score" role="tab" aria-selected="true">Nilai KPI</button><button type="button" data-panel-tab="findings" role="tab" aria-selected="false">Temuan</button><button type="button" data-panel-tab="history" data-history-tab role="tab" aria-selected="false" hidden>Jejak keputusan</button></div>
<div data-panel="score"><div class="table-wrap"><table class="data-table score-table"><thead><tr><th>KPI dan target</th><th class="numeric">Bobot</th><th class="numeric">Nilai</th><th class="numeric">Hasil</th></tr></thead><tbody data-score-rows></tbody></table></div></div>
<div data-panel="findings" hidden><div class="grid gap-4 min-[850px]:grid-cols-2"><label><span class="label">Temuan positif (opsional)</span><textarea class="field min-h-24" data-finding="positive" maxlength="10000"></textarea><p data-read-finding="positive" class="text-sm leading-6" hidden></p></label><label><span class="label">Temuan negatif (opsional)</span><textarea class="field min-h-24" data-finding="negative" maxlength="10000"></textarea><p data-read-finding="negative" class="text-sm leading-6" hidden></p></label></div></div>
<div data-panel="history" hidden><ol data-review-history class="space-y-3 text-xs text-muted"></ol></div>
<div class="score-summary"><p class="text-xs text-muted"><span data-filled></span> KPI terisi · bobot <b data-score-weight></b>%<br>Nilai bulat 10–100 · hasil = nilai × bobot / 100</p><div class="flex items-center gap-3"><strong class="num text-[28px]" data-total></strong><span class="category text-sm font-semibold" data-category></span></div></div>
<p class="notice notice-error mt-3" data-score-error hidden role="alert"></p></section></template>
<template id="flow-score-item"><tr><td><strong class="font-semibold" data-kpi-name></strong><span class="mt-1 block text-xs text-muted" data-kpi-meta></span><span class="mt-1 block text-xs text-muted" data-previous></span></td><td class="numeric" data-label="Bobot" data-weight></td><td class="numeric" data-label="Nilai"><label><span class="sr-only" data-score-label></span><input class="score-input num" type="text" inputmode="numeric" autocomplete="off" maxlength="5" placeholder="-" data-score></label><strong data-read-score hidden></strong></td><td class="numeric font-semibold" data-label="Hasil" data-result></td></tr></template>
@endonce
